from pypdf import PdfReader
import re
reader=PdfReader('/root/SimPO/paper.pdf')
text=[]
for i,p in enumerate(reader.pages):
    t=p.extract_text() or ''
    if 'SimPO' in t or 'loss' in t or 'gamma' in t or 'beta' in t:
        text.append((i,t))
