for i,t in text:
    if pattern.search(t):
        # print snippet around 'SimPO loss'
        if re.search(r"SimPO.*loss|loss.*SimPO",t,re.I) or 'gamma' in t or 'beta' in t:
            print('\n=== page',i+1,'===')
            # print first 2000 chars for page
            print(t[:2000].replace('\n',' '))
